    // @port: Daqifi.Desktop.Logger.LoggingManager.OnActiveChanged
    partial void OnActiveChanged(bool oldValue, bool newValue)
    {
        if (!newValue && oldValue) // Was active, now stopping
        {
            if (_hasActiveApplicationSession && Session != null)
            {
                if (_hasActiveApplicationSamples)
                {
                    if (!LoggingSessions.Any(s => s.ID == Session.ID))
                    {
                        LoggingSessions.Add(Session);
                    }

                    // Finalize the session by recording its sample count so the
                    // list view never has to count rows. Runs on a background
                    // thread because COUNT(*) on a multi-million-row session
                    // would otherwise block the UI thread that toggled Active.
                    // The list row updates automatically when SampleCount is
                    // set, since LoggingSession is INotifyPropertyChanged.
                    var sessionToFinalize = Session;
                    _ = Task.Run(() => PersistSessionSampleCount(sessionToFinalize));
                }
                else
                {
                    DeleteLoggingSessionIfPresent(Session.ID);
                }
            }

            _hasActiveApplicationSession = false;
            _hasActiveApplicationSamples = false;
        }
        else if (newValue && !oldValue) // Was inactive, now starting
        {
            foreach (var channel in SubscribedChannels.ToList())
            {
                channel.OnChannelUpdated -= HandleChannelUpdate;
            }

            // Clear loggers
            foreach (var logger in Loggers)
            {
                if (logger is PlotLogger plotLogger)
                {
                    plotLogger.ClearPlot();
                }
                else if (logger is DatabaseLogger dbLogger)
                {
                    dbLogger.ClearPlot();
                }
            }

            if (CurrentMode != LoggingMode.Stream)
            {
                _hasActiveApplicationSession = false;
                _hasActiveApplicationSamples = false;
                return;
            }

            using (var context = _loggingContext.CreateDbContext())
            {
                // Pick an ID that cannot collide with any existing row in any
                // related table. Sessions.ID is manually assigned (not IDENTITY),
                // so reusing the max+1 across only the Sessions table can hand
                // out an ID that is still referenced by orphan rows in
                // SessionDeviceMetadata or Samples (e.g., from a prior crash, or
                // a delete that ran without SQLite foreign keys enabled). The
                // composite PK on SessionDeviceMetadata then rejects the insert
                // with UNIQUE constraint failed and the toggle appears to do
                // nothing on the second attempt.
                //
                // This runs synchronously on the UI thread (IsLogging is a
                // UI-bound toggle), so the cost matters as the database grows.
                // Folding the three MAXes into a single SQL statement keeps the
                // round-trip count at one. Each inner MAX hits an index — Sessions.ID
                // is the PK, SessionDeviceMetadata.LoggingSessionID is the leading
                // column of the composite PK, and Samples has IX_Samples_SessionTime
                // on (LoggingSessionID, TimestampTicks) — so SQLite resolves each
                // MAX as an index seek rather than a table scan.
                const string nextSessionIdSql = @"
                    SELECT MAX(id) AS Value FROM (
                        SELECT MAX(ID) AS id FROM Sessions
                        UNION ALL SELECT MAX(LoggingSessionID) AS id FROM SessionDeviceMetadata
                        UNION ALL SELECT MAX(LoggingSessionID) AS id FROM Samples
                    )";
                var maxKnownId = context.Database.SqlQueryRaw<int?>(nextSessionIdSql)
                    .AsEnumerable()
                    .FirstOrDefault() ?? -1;
                var newId = maxKnownId + 1;
                var name = $"Session_{newId}";
                Session = new LoggingSession(newId, name);
                context.Sessions.Add(Session);

                // Capture per-device metadata (sampling frequency, name) for the
                // devices that own the subscribed channels, so the session UI can
                // display configuration without re-deriving it from sample data.
                // Failures here must not block session creation — the session is
                // still usable without metadata; the legend just won't show
                // sampling frequency.
                try
                {
                    foreach (var metadata in BuildDeviceMetadataForSession(newId))
                    {
                        // EF Core's relationship fix-up automatically attaches
                        // this row to Session.DeviceMetadata because the FK
                        // matches the tracked Session. Adding to the nav
                        // collection explicitly would insert the same CLR
                        // reference a second time, making FrequencyDisplay show
                        // duplicate entries until the next reload.
                        context.SessionDeviceMetadata.Add(metadata);
                    }
                }
                catch (Exception ex)
                {
                    AppLogger.Error(ex, $"Failed to capture device metadata for session {newId}; continuing without it.");
                }

                context.SaveChanges();
            }

            _hasActiveApplicationSession = true;
            _hasActiveApplicationSamples = false;

            // Resubscribe channels
            foreach (var channel in SubscribedChannels.ToList())
            {
                channel.OnChannelUpdated += HandleChannelUpdate;
            }
        }
    }

