    // @port: Daqifi.Desktop.Logger.LoggingManager.LoadPersistedLoggingSessions
    public ObservableCollection<LoggingSession> LoadPersistedLoggingSessions()
    {
        using var context = _loggingContext.CreateDbContext();

        var emptySessions = context.Sessions
            .Where(session => !context.Samples.Any(sample => sample.LoggingSessionID == session.ID))
            .ToList();

        if (emptySessions.Count > 0)
        {
            context.Sessions.RemoveRange(emptySessions);
            context.SaveChanges();
        }

        // Sweep orphan SessionDeviceMetadata rows whose Sessions row is gone.
        // SQLite cascade delete only fires when PRAGMA foreign_keys=ON for the
        // active connection; if any prior delete ran without it, metadata for
        // long-gone sessions can linger and collide with future session IDs
        // (the composite PK rejects the new insert with UNIQUE constraint
        // failed on SessionDeviceMetadata). Clearing them at startup makes
        // the database self-heal on the next launch.
        try
        {
            context.Database.ExecuteSqlRaw(
                "DELETE FROM SessionDeviceMetadata WHERE LoggingSessionID NOT IN (SELECT ID FROM Sessions)");
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, "Failed to clean orphan SessionDeviceMetadata rows on startup.");
        }

        // One-time backfill: any session created before the SampleCount column
        // existed (or whose count was lost mid-run) gets counted in a single
        // GROUP BY query, then UPDATEd. Subsequent loads pay no cost.
        BackfillMissingSampleCounts(context);

        return new ObservableCollection<LoggingSession>(
            context.Sessions
                .AsNoTracking()
                .Include(session => session.DeviceMetadata)
                .Where(session => context.Samples.Any(sample => sample.LoggingSessionID == session.ID))
                .OrderBy(session => session.ID)
                .ToList());
    }

    /// <summary>
    /// PURE read of the persisted sessions-with-samples list — no purge, no orphan sweep,
    /// no backfill (unlike <see cref="LoadPersistedLoggingSessions"/>). Safe to call
    /// repeatedly and concurrently with a live writer: an in-flight SD-card import commits
    /// its <c>Sessions</c> row with zero samples first, so the empty-session purge in
    /// <see cref="LoadPersistedLoggingSessions"/> would DELETE that in-flight row and corrupt
    /// the import. This variant only SELECTs (the 0-sample import row is naturally excluded
    /// by the <c>Samples.Any</c> filter until it has data), so a refresh can never destroy it.
    /// Used by the mobile Storage pane, which re-reads on every visit.
    /// </summary>
    public ObservableCollection<LoggingSession> GetLoggingSessionsSnapshot()
    {
        using var context = _loggingContext.CreateDbContext();
        return new ObservableCollection<LoggingSession>(
            context.Sessions
                .AsNoTracking()
                .Include(session => session.DeviceMetadata)
                .Where(session => context.Samples.Any(sample => sample.LoggingSessionID == session.ID))
                .OrderBy(session => session.ID)
                .ToList());
    }

    /// <summary>
    /// Persists <see cref="LoggingSession.SampleCount"/> for the given session
    /// by running a single COUNT against the Samples table. Called when a
    /// session ends so the list view can surface the count without a query.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.LoggingManager.PersistSessionSampleCount
    private void PersistSessionSampleCount(LoggingSession session)
    {
        try
        {
            // Wait for any buffered samples in DatabaseLogger to be flushed to
            // disk before counting. Without this, the COUNT can race the
            // background consumer and persist a permanent undercount, since
            // BackfillMissingSampleCounts only repairs null values.
            var dbLogger = Loggers?.OfType<DatabaseLogger>().FirstOrDefault();
            dbLogger?.WaitForIdle(TimeSpan.FromSeconds(10));

            using var context = _loggingContext.CreateDbContext();
            var count = context.Samples.LongCount(s => s.LoggingSessionID == session.ID);

            var tracked = context.Sessions.FirstOrDefault(s => s.ID == session.ID);
            if (tracked != null)
            {
                tracked.SampleCount = count;
                context.SaveChanges();
            }

            // Surface the finalized count so a session end is observable out-of-process
            // (the UI-test harness reads this line to learn the persisted sample count it
            // then cross-checks against an exported CSV). All buffered samples are already
            // flushed (WaitForIdle above), so this is the authoritative per-session total.
            AppLogger.Information($"Persisted sample count {count} for session {session.ID}");

            // Test-mode-only companion oracle for the CSV export harness: the number of
            // DISTINCT (timestamp, device, serial, channel) positions. The device occasionally
            // re-emits a frame with a duplicated timestamp tick mid-session, and the CSV
            // exporters intentionally collapse same-position duplicates into one cell
            // (last value wins) — so the raw sample count overstates the exported cell count
            // whenever a session contains such a frame. This DISTINCT can cost ~a second on
            // million-sample sessions, so it never runs in production.
            if (Daqifi.Desktop.Common.AppDataPaths.IsTestMode)
            {
                var distinctPositions = context.Samples
                    .Where(s => s.LoggingSessionID == session.ID)
                    .Select(s => new { s.TimestampTicks, s.DeviceName, s.DeviceSerialNo, s.ChannelName })
                    .Distinct()
                    .LongCount();
                AppLogger.Information(
                    $"Persisted distinct sample positions {distinctPositions} for session {session.ID}");
            }

            // Marshal the in-memory mutation onto the UI thread so the
            // PropertyChanged notification fires on the dispatcher and
            // bindings update safely (WPF Application.Current.Dispatcher -> Dispatcher.UIThread).
            if (!Dispatcher.UIThread.CheckAccess())
            {
                Dispatcher.UIThread.Invoke(() => session.SampleCount = count);
            }
            else
            {
                session.SampleCount = count;
            }
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, $"Failed to persist sample count for session {session?.ID}");
        }
    }

    /// <summary>
    /// Lazily backfills <see cref="LoggingSession.SampleCount"/> for any
    /// session whose count is null. Uses a single GROUP BY query covering all
    /// missing sessions at once, then issues UPDATEs in one transaction. Runs
    /// at most once per session over the lifetime of the database.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.LoggingManager.BackfillMissingSampleCounts
    private void BackfillMissingSampleCounts(LoggingContext context)
    {
        try
        {
            var sessionsMissingCount = context.Sessions
                .Where(s => s.SampleCount == null)
                .Select(s => s.ID)
                .ToList();

            if (sessionsMissingCount.Count == 0) { return; }

            var countsBySession = context.Samples
                .Where(sample => sessionsMissingCount.Contains(sample.LoggingSessionID))
                .GroupBy(sample => sample.LoggingSessionID)
                .Select(g => new { SessionId = g.Key, Count = g.LongCount() })
                .ToDictionary(g => g.SessionId, g => g.Count);

            var trackedSessions = context.Sessions
                .Where(s => sessionsMissingCount.Contains(s.ID))
                .ToList();

            foreach (var tracked in trackedSessions)
            {
                tracked.SampleCount = countsBySession.TryGetValue(tracked.ID, out var c) ? c : 0;
            }

            context.SaveChanges();
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, "Failed to backfill SampleCount for legacy sessions");
        }
    }

    /// <summary>
    /// Reloads persisted logging sessions from storage and repopulates the current collection in place.
    /// </summary>
    // @port: Daqifi.Desktop.Logger.LoggingManager.ReloadPersistedLoggingSessions
    public void ReloadPersistedLoggingSessions()
    {
        var persistedSessions = LoadPersistedLoggingSessions();
        LoggingSessions.Clear();

        foreach (var session in persistedSessions)
        {
            LoggingSessions.Add(session);
        }
    }

    // @port: Daqifi.Desktop.Logger.LoggingManager.DeleteLoggingSessionIfPresent
    private void DeleteLoggingSessionIfPresent(int sessionId)
    {
        var existingSession = LoggingSessions.FirstOrDefault(session => session.ID == sessionId);
        if (existingSession != null)
        {
            LoggingSessions.Remove(existingSession);
        }

        try
        {
            using var context = _loggingContext.CreateDbContext();
            var connection = context.Database.GetDbConnection();
            connection.Open();

            using var transaction = connection.BeginTransaction();

            using (var cmd = connection.CreateCommand())
            {
                cmd.Transaction = transaction;
                cmd.CommandText = "DELETE FROM Samples WHERE LoggingSessionID = @id";
                var param = cmd.CreateParameter();
                param.ParameterName = "@id";
                param.Value = sessionId;
                cmd.Parameters.Add(param);
                cmd.ExecuteNonQuery();
            }

            using (var cmd = connection.CreateCommand())
            {
                cmd.Transaction = transaction;
                cmd.CommandText = "DELETE FROM SessionDeviceMetadata WHERE LoggingSessionID = @id";
                var param = cmd.CreateParameter();
                param.ParameterName = "@id";
                param.Value = sessionId;
                cmd.Parameters.Add(param);
                cmd.ExecuteNonQuery();
            }

            using (var cmd = connection.CreateCommand())
            {
                cmd.Transaction = transaction;
                cmd.CommandText = "DELETE FROM Sessions WHERE ID = @id";
                var param = cmd.CreateParameter();
                param.ParameterName = "@id";
                param.Value = sessionId;
                cmd.Parameters.Add(param);
                cmd.ExecuteNonQuery();
            }

            transaction.Commit();
        }
        catch (Exception ex)
        {
            AppLogger.Error(ex, $"Failed to delete logging session {sessionId}");
        }
    }

    // @port: Daqifi.Desktop.Logger.LoggingManager.ClearChannelList
    private void ClearChannelList()
    {
        lock (_subscribedChannelsSync)
        {
            foreach (var channel in _subscribedChannels)
            {
                channel.IsActive = false;
                channel.OnChannelUpdated -= HandleChannelUpdate;
            }

            // Copy-on-write -- see SubscribedChannels' remarks. Clear() would empty the very list a
            // reader on the transport thread may be enumerating; the empty array is immutable.
            Volatile.Write(ref _subscribedChannels, Array.Empty<IChannel>());
        }

        // Raised outside the lock so a binding handler can never re-enter under it.
        OnPropertyChanged(nameof(SubscribedChannels));
    }
}
